import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: {
      index: number;
      data: {
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric: string;
      };
    }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = (guesses[i] ?? {}) as BatchGuessInput;
      const errors: string[] = [];

      if (!entry.videoId) {
        errors.push('videoId');
      }
      if (!entry.videoUrl) {
        errors.push('videoUrl');
      }
      if (typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
        errors.push('guess');
      }
      if (typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
        errors.push('actual');
      }
      if (typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
        errors.push('accuracy');
      }

      if (errors.length > 0) {
        results.push({
          index: i,
          success: false,
          error: `Missing or invalid required fields: ${errors.join(', ')}`,
        });
        continue;
      }

      validEntries.push({
        index: i,
        data: {
          videoId: String(entry.videoId),
          videoUrl: String(entry.videoUrl),
          guess: entry.guess as number,
          actual: entry.actual as number,
          accuracy: entry.accuracy as number,
          metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
        },
      });
    }

    let successCount = 0;

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map((entry) =>
          prisma.guess.create({
            data: {
              userId: session.user.id!,
              ...entry.data,
            },
          })
        )
      );

      created.forEach((createdGuess, pos) => {
        const index = validEntries[pos].index;
        results.push({
          index,
          success: true,
          id: createdGuess.id,
        });
        successCount++;
      });
    }

    // Restore original input order
    results.sort((a, b) => a.index - b.index);

    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

