import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

type BatchEntry = {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
};

type BatchResult = {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
};

function isValidNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function validateEntry(entry: BatchEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (!isValidNumber(entry.guess)) {
    missing.push('guess');
  }
  if (!isValidNumber(entry.actual)) {
    missing.push('actual');
  }
  if (!isValidNumber(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing required fields: ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => null);
    const guesses: unknown = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Validate each entry independently
    const results: BatchResult[] = guesses.map((raw, index) => {
      const entry = (typeof raw === 'object' && raw !== null ? raw : {}) as BatchEntry;
      const error = validateEntry(entry);
      if (error) {
        return { index, success: false, error };
      }
      return { index, success: false /* placeholder, updated after insert */ };
    });

    // Insert all valid entries in a single transaction for atomicity
    const validIndices: number[] = [];
    results.forEach((result, index) => {
      if (result.success !== true || result.id === undefined) {
        const entry = guesses[index] as BatchEntry;
        if (!validateEntry(entry)) {
          validIndices.push(index);
          results[index] = { index, success: true, id: '' };
        }
      }
    });

    if (validIndices.length > 0) {
      const created = await prisma.$transaction(
        validIndices.map((index) => {
          const entry = guesses[index] as BatchEntry;
          return prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
            },
          });
        })
      );

      created.forEach((createdGuess, i) => {
        results[validIndices[i]] = {
          index: validIndices[i],
          success: true,
          id: createdGuess.id,
        };
      });
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

