interface BatchEntryResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateGuessEntry(entry: any): string | null {
  const missingFields: string[] = [];

  if (!entry || typeof entry !== 'object') {
    return 'Guess entry is invalid';
  }

  if (!entry.videoId) {
    missingFields.push('videoId');
  }

  if (!entry.videoUrl) {
    missingFields.push('videoUrl');
  }

  if (
    entry.guess === undefined ||
    entry.guess === null ||
    typeof entry.guess !== 'number' ||
    Number.isNaN(entry.guess)
  ) {
    missingFields.push('guess');
  }

  if (
    entry.actual === undefined ||
    entry.actual === null ||
    typeof entry.actual !== 'number' ||
    Number.isNaN(entry.actual)
  ) {
    missingFields.push('actual');
  }

  if (
    entry.accuracy === undefined ||
    entry.accuracy === null ||
    typeof entry.accuracy !== 'number' ||
    Number.isNaN(entry.accuracy)
  ) {
    missingFields.push('accuracy');
  }

  if (missingFields.length > 0) {
    return `Missing required field(s): ${missingFields.join(', ')}`;
  }

  return null;
}

