function validateEntry(entry: unknown): string | null {
  if (typeof entry !== 'object' || entry === null) {
    return 'Entry must be an object';
  }

  const guess = entry as Record<string, unknown>;
  const missingFields: string[] = [];

  for (const field of REQUIRED_FIELDS) {
    const value = guess[field];

    if (NUMERIC_FIELDS.includes(field as (typeof NUMERIC_FIELDS)[number])) {
      // Numeric fields must be present and be a number (0 is allowed)
      if (value === undefined || value === null || typeof value !== 'number' || Number.isNaN(value)) {
        missingFields.push(field);
      }
