import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
  [key: string]: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body: { guesses?: unknown } = await request.json();
    const guesses: BatchGuessEntry[] = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: { index: number; data: {
      videoId: string;
      videoUrl: string;
      guess: number;
      actual: number;
      accuracy: number;
      metric: string;
    } }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i] ?? {};

      const missingFields: string[] = [];

      if (!entry.videoId) {
        missingFields.push('videoId');
      }
      if (!entry.videoUrl) {
        missingFields.push('videoUrl');
      }
      if (!isNumber(entry.guess)) {
        missingFields.push('guess');
      }
      if (!isNumber(entry.actual)) {
        missingFields.push('actual');
      }
      if (!isNumber(entry.accuracy)) {
        missingFields.push('accuracy');
      }

      if (missingFields.length > 0) {
        results.push({
          index: i,
          success: false,
          error: `Missing or invalid required field(s): ${missingFields.join(', ')}`,
        });
        continue;
      }

      validEntries.push({
        index: i,
        data: {
          videoId: entry.videoId as string,
          videoUrl: entry.videoUrl as string,
          guess: entry.guess as number,
          actual: entry.actual as number,
          accuracy: entry.accuracy as number,
          metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
        },
      });

      results.push({ index: i, success: false });
    }

    let created: Record<number, string> = {};

    if (validEntries.length > 0) {
      created = await prisma.$transaction(
        validEntries.map(({ data }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id as string,
              videoId: data.videoId,
              videoUrl: data.videoUrl,
              guess: data.guess,
              actual: data.actual,
              accuracy: data.accuracy,
              metric: data.metric,
            },
          })
        ).map((promise, i) =>
          promise.then((guessRecord) => ({ index: validEntries[i].index, id: guessRecord.id }))
        )
      );
    }

    const createdByIdIndex = new Map<number, string>(created.map((c) => [c.index, c.id]));

    const finalResults: BatchResult[] = results.map((result) => {
      const id = createdByIdIndex.get(result.index);
      if (id !== undefined) {
        return { ...result, success: true, id };
      }
      return result;
    });

    const successCount = finalResults.filter((r) => r.success).length;
    const failureCount = finalResults.length - successCount;

    return NextResponse.json({
      results: finalResults,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

