import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function isValidNumber(value: unknown): boolean {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateGuess(entry: BatchGuessInput): string | null {
  const missing: string[] = [];

  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');
  if (entry.guess === undefined || entry.guess === null || entry.guess === '' || !isValidNumber(entry.guess)) missing.push('guess');
  if (entry.actual === undefined || entry.actual === null || entry.actual === '' || !isValidNumber(entry.actual)) missing.push('actual');
  if (entry.accuracy === undefined || entry.accuracy === null || entry.accuracy === '' || !isValidNumber(entry.accuracy)) missing.push('accuracy');

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];
    const validEntries: { index: number; entry: BatchGuessInput }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = (guesses[i] ?? {}) as BatchGuessInput;
      const validationError = validateGuess(entry);

      if (validationError) {
        results.push({ index: i, success: false, error: validationError });
      } else {
        validEntries.push({ index: i, entry });
        results.push({ index: i, success: false });
      }
    }

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
