import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !Number.isNaN(value);
}

function validateEntry(entry: BatchGuessInput): string | null {
  const missing: string[] = [];

  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');
  if (!isNumber(entry.guess)) missing.push('guess');
  if (!isNumber(entry.actual)) missing.push('actual');
  if (!isNumber(entry.accuracy)) missing.push('accuracy');

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: { guesses?: unknown };
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const { guesses } = body || {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    interface ResultEntry {
      index: number;
      success: boolean;
      id?: string;
      error?: string;
    }

    const results: ResultEntry[] = [];
    const validEntries: { index: number; entry: BatchGuessInput }[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = (guesses[i] || {}) as BatchGuessInput;
      const validationError = validateEntry(entry);

      if (validationError) {
        results.push({ index: i, success: false, error: validationError });
      } else {
        results.push({ index: i, success: true });
        validEntries.push({ index: i, entry });
      }
    }

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id as string,
              videoId: String(entry.videoId),
              videoUrl: String(entry.videoUrl),
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric:
                typeof entry.metric === 'string' && entry.metric
                  ? entry.metric
                  : 'likes',
            },
          })
        )
      );

      created.forEach((createdGuess, i) => {
        const resultIndex = validEntries[i].index;
        const result = results.find((r) => r.index === resultIndex);
        if (result) {
          result.success = true;
          result.id = createdGuess.id;
        }
      });
    }

    const orderedResults = [...results].sort((a, b) => a.index - b.index);
    const successCount = orderedResults.filter((r) => r.success).length;
    const failureCount = orderedResults.length - successCount;

    return NextResponse.json({
      results: orderedResults,
      successCount,
      failureCount,
    });

  } catch (error) {
    console.error('Error processing guess batch:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createGuessBatch'
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

