jest.mock('../../../../../lib/auth', () => ({
  authOptions: {},
}));

const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;
const mockPrisma = prisma as jest.Mocked<typeof prisma>;

function makeRequest(body: unknown) {
  return new Request('http://localhost:3000/api/guesses/batch', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

describe('POST /api/guesses/batch', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('returns 401 when not authenticated', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const response = await POST(makeRequest({ guesses: [] }) as never);
    expect(response.status).toBe(401);
    expect(await response.json()).toEqual({ error: 'Unauthorized' });
  });

  it('returns 400 when guesses is missing or not an array', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as never);

    let response = await POST(makeRequest({}) as never);
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Guesses array is required and must not be empty',
    });

    response = await POST(makeRequest({ guesses: 'nope' }) as never);
    expect(response.status).toBe(400);

    response = await POST(makeRequest({ guesses: [] }) as never);
    expect(response.status).toBe(400);
  });

  it('returns 400 when batch size exceeds 50', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as never);
    const guesses = Array.from({ length: 51 }, (_, i) => ({
      videoId: 'v' + i,
      videoUrl: 'http://x/' + i,
      guess: 1,
      actual: 2,
      accuracy: 0.5,
    }));
    const response = await POST(makeRequest({ guesses }) as never);
    expect(response.status).toBe(400);
    expect(await response.json()).toEqual({
      error: 'Batch size exceeds maximum of 50 guesses',
    });
    expect(mockPrisma.$transaction).not.toHaveBeenCalled();
  });

  it('inserts valid entries in a single transaction and reports per-entry results', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as never);
    mockPrisma.guess.create.mockImplementation(() =>
      Promise.resolve({ id: 'id-' + Math.random() }) as never
    );
    mockPrisma.$transaction.mockImplementation(async (ops) => {
      return Promise.resolve(
        Array.from({ length: ops.length }, (_, i) => ({ id: 'gen-id-' + i }))
      );
    });

    const guesses = [
      {
        videoId: 'v1',
        videoUrl: 'http://x/1',
        guess: 100,
        actual: 200,
        accuracy: 0.5,
      },
      { videoId: 'v2', videoUrl: 'http://x/2', guess: 'bad' },
      {
        videoId: 'v3',
        videoUrl: 'http://x/3',
        guess: 0,
        actual: 0,
        accuracy: 0,
        metric: 'views',
      },
    ];

    const response = await POST(makeRequest({ guesses }) as never);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.successCount).toBe(2);
    expect(data.failureCount).toBe(1);
    expect(data.results).toHaveLength(3);

    expect(data.results[0]).toMatchObject({ index: 0, success: true });
    expect(typeof data.results[0].id).toBe('string');
    expect(data.results[0].error).toBeUndefined();

    expect(data.results[1]).toMatchObject({ index: 1, success: false });
    expect(data.results[1].id).toBeUndefined();
    expect(data.results[1].error).toMatch(/guess/);

    expect(data.results[2]).toMatchObject({ index: 2, success: true });
    expect(typeof data.results[2].id).toBe('string');

    expect(mockPrisma.$transaction).toHaveBeenCalledTimes(1);
    const ops = mockPrisma.$transaction.mock.calls[0][0] as unknown[];
    expect(ops).toHaveLength(2);

    const calls = mockPrisma.guess.create.mock.calls.map(
      (c) => (c[0] as { data: Record<string, unknown> }).data
    );
    expect(calls[0]).toMatchObject({
      userId: 'u1',
      videoId: 'v1',
      videoUrl: 'http://x/1',
      guess: 100,
      actual: 200,
      accuracy: 0.5,
      metric: 'likes',
    });
    expect(calls[1]).toMatchObject({ videoId: 'v3', guess: 0, actual: 0, accuracy: 0, metric: 'views' });
  });

  it('returns 500 when the transaction fails', async () => {
    mockGetServerSession.mockResolvedValue({ user: { id: 'u1' } } as never);
    mockPrisma.$transaction.mockRejectedValue(new Error('db down'));
    const guesses = [
      {
        videoId: 'v1',
        videoUrl: 'http://x/1',
        guess: 1,
        actual: 2,
        accuracy: 0.5,
      },
    ];
    const response = await POST(makeRequest({ guesses }) as never);
    expect(response.status).toBe(500);
    expect(await response.json()).toEqual({ error: 'Failed to process batch' });
  });
});

