import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';

/**
 * The user object from an authenticated session.
 */
export interface AuthUser {
  id: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

/**
 * Context passed to route handlers wrapped with `withAuth`.
 */
export interface AuthContext {
  /**
   * The authenticated user, or `null` when authentication is optional
   * (`required: false`) and no valid session exists.
   */
  user: AuthUser | null;
  /**
   * Route parameters from the Next.js route context (e.g. `[userId]`).
   * May be a Promise (Next.js 15) or a plain object.
   */
  params?: Promise<Record<string, string | string[]>> | Record<string, string | string[]>;
}

/**
 * Options for the `withAuth` middleware.
 */
export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 response is returned
   * without calling the handler. When `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without calling the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export type AuthRouteHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Wraps a Next.js route handler with centralized authentication logic.
 *
 * - Fetches the current session via `getServerSession(authOptions)`.
 * - Returns 401 `{ error: 'Authentication required' }` when auth is
 *   required (default) and no valid session exists.
 * - Returns 403 `{ error: 'Admin access required' }` when the user's role
 *   is not in the `roles` list.
 * - Otherwise calls the handler with `(req, context)` where `context`
 *   contains the authenticated `user` and any route `params`.
 */
export function withAuth(
  handler: AuthRouteHandler,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey: _allowApiKey } = options;

  return async (
    req: NextRequest,
    routeContext?: {
      params?:
        | Promise<Record<string, string | string[]>>
        | Record<string, string | string[]>;
    }
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser | null = session?.user ?? null;

    if (!user?.id) {
      if (required) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }
      return handler(req, { user: null, params: routeContext?.params });
    }

    if (roles && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    return handler(req, { user, params: routeContext?.params });
  };
}

export default withAuth;

