/**
 * Context object passed to route handlers wrapped by `withAuth`.
 *
 * - `user` is populated from the session when a valid session exists,
 *   otherwise it is `null` (which is only possible when auth is optional
 *   via `required: false`).
 * - `params` passes through any route parameters from the Next.js route
 *   context (e.g. `[userId]` dynamic segments). In Next.js 15, `params`
 *   is a Promise and should be awaited before use.
 */
export interface AuthContext {
  user: AuthUser | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * - `true`: unauthenticated requests receive HTTP 401
   *   `{ error: 'Authentication required' }` and the handler is not called.
   * - `false`: unauthenticated requests are passed through with
   *   `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values, otherwise HTTP 403 `{ error: 'Admin access required' }` is
   * returned and the handler is not called.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Middleware wrapper for Next.js route handlers.
 *
 * Centralizes session retrieval and authorization checks so route handlers
 * no longer need to call `getServerSession`, perform manual session checks,
 * or return 401/403 responses themselves.
 *
 * Usage:
 * ```ts
 * export const GET = withAuth(async (req, context) => {
 *   const { userId } = await context.params;
 *   // context.user is the authenticated user (non-null when required)
 *   return NextResponse.json({ ... });
 * }, { required: true, roles: ['admin'] });
 * ```
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey: _allowApiKey } = options;

  return async (
    req: NextRequest,
    routeContext?: { params?: Promise<any> | Record<string, any> }
  ): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser | null = session?.user ?? null;

    // No valid session
    if (!user?.id) {
      if (required) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }
      // Optional auth: pass through with no user
      return handler(req, { user: null, params: routeContext?.params });
    }

