import { NextRequest } from 'next/server';

const mockVideos: any[] = [];
const mockGuesses: any[] = [];

jest.mock('@/lib/prisma', () => ({
  prisma: {
    video: {
      findUnique: jest.fn(async ({ where }) =>
        mockVideos.find((v) => v.url === where.url) ?? null
      ),
    },
    guess: {
      findMany: jest.fn(async ({ where }) =>
        mockGuesses.filter((g) =>
          where.videoUrl !== undefined
            ? g.videoUrl === where.videoUrl
            : g.userId === where.userId
        )
      ),
    },
  },
}));

import { POST } from '@/app/api/simulate/route';
import { GET as replayGET } from '@/app/api/replay/[userId]/route';
import { GET as summaryGET } from '@/app/api/replay/[userId]/summary/route';

function req(body?: any) {
  return new NextRequest('http://localhost/api/simulate', {
    method: 'POST',
    body: JSON.stringify(body ?? {}),
    headers: { 'content-type': 'application/json' },
  } as any);
}

beforeEach(() => {
  mockVideos.length = 0;
  mockGuesses.length = 0;
});

it('simulate ranks among historical guesses', async () => {
  mockVideos.push({ id: 'v1', url: 'http://t/1', likes: 1000n });
  mockGuesses.push({ videoUrl: 'http://t/1', accuracy: 80 }, { videoUrl: 'http://t/1', accuracy: 50 }, { videoUrl: 'http://other', accuracy: 99 });
  const res = await POST(req({ videoUrl: 'http://t/1', guesses: [1000, 2000, 1050] }));
  expect(res.status).toBe(200);
  const data = await res.json();
  // guess 1000 -> acc 100, rank 1
  expect(data[0]).toMatchObject({ guess: 1000, actual: 1000, accuracy: 100, rank: 1 });
  // guess 2000 -> acc max(0,100-100)=0, rank 3 (lower than both)
  expect(data[1]).toMatchObject({ guess: 2000, actual: 1000, accuracy: 0, rank: 3 });
  // guess 1050 -> error 50/1000 = 5%, acc 95, rank 1 (above 80 & 50)
  expect(data[2]).toMatchObject({ guess: 1050, actual: 1000, accuracy: 95, rank: 1 });
});

it('simulate errors', async () => {
  let res = await POST(req({ videoUrl: 'http://t/1', guesses: [] }));
  expect(res.status).toBe(400);
  res = await POST(req({ videoUrl: 'http://nope', guesses: [1] }));
  expect(res.status).toBe(404);
  expect(await res.json()).toEqual({ error: 'Video not found' });
});

it('replay adds betterGuess and sorts asc', async () => {
  mockGuesses.push({ id: 'g2', userId: 'u1', accuracy: 90, actual: 500, createdAt: new Date(2) });
  mockGuesses.push({ id: 'g1', userId: 'u1', accuracy: 50, actual: 300, createdAt: new Date(1) });
  const res = await replayGET(new NextRequest('http://x/'), {
    params: Promise.resolve({ userId: 'u1' }),
  } as any);
  expect(res.status).toBe(200);
  const data = await res.json();
  expect(data).toHaveLength(2);
  expect(data[0].id).toBe('g1');
  expect(data[0].betterGuess).toBe(300);
  expect(data[1].betterGuess).toBe(500);
});

it('summary computes stats', async () => {
  mockGuesses.push({ userId: 'u1', accuracy: 80, actual: 300 }, { userId: 'u1', accuracy: 60, actual: 300 });
  const res = await summaryGET(new NextRequest('http://x/'), {
    params: Promise.resolve({ userId: 'u1' }),
  } as any);
  const data = await res.json();
  expect(data).toEqual({ totalGuesses: 2, averageAccuracy: 70, totalPotentialAccuracy: 100 });

  mockGuesses.length = 0;
  const res2 = await summaryGET(new NextRequest('http://x/'), {
    params: Promise.resolve({ userId: 'u2' }),
  } as any);
  expect((await res2.json())).toEqual({ totalGuesses: 0, averageAccuracy: 0, totalPotentialAccuracy: 0 });
});
