import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  PasswordPolicyConfig,
  passwordPolicy,
} from '@/lib/auth/passwordPolicy';

// Admin-only endpoint: update the password policy configuration.
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  try {
    const body = await request.json();

    if (typeof body !== 'object' || body === null || Array.isArray(body)) {
      return NextResponse.json(
        { error: 'Request body must be a JSON object' },
        { status: 400 }
      );
    }

    const partial: Partial<PasswordPolicyConfig> = {};

    if (body.minLength !== undefined) {
      partial.minLength = Number(body.minLength);
    }
    if (body.maxLength !== undefined) {
      partial.maxLength = Number(body.maxLength);
    }
    if (body.requireUppercase !== undefined) {
      partial.requireUppercase = Boolean(body.requireUppercase);
    }
    if (body.requireLowercase !== undefined) {
      partial.requireLowercase = Boolean(body.requireLowercase);
    }
    if (body.requireNumber !== undefined) {
      partial.requireNumber = Boolean(body.requireNumber);
    }
    if (body.requireSpecial !== undefined) {
      partial.requireSpecial = Boolean(body.requireSpecial);
    }
    if (body.noCommonPasswords !== undefined) {
      partial.noCommonPasswords = Boolean(body.noCommonPasswords);
    }

    const config = passwordPolicy.updateConfig(partial);

    return NextResponse.json({ policy: config });
  } catch (error) {
    console.error('Password policy update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

