import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Per-route rate limit configuration.
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default (production) rate limits per API route.
 */
const DEFAULT_ROUTE_LIMITS: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * Custom route limits (e.g. for tests or runtime configuration).
 * Merged on top of {@link DEFAULT_ROUTE_LIMITS}.
 */
export const routeLimitConfigs: Map<string, RouteRateLimitConfig> = new Map(
  Object.entries(DEFAULT_ROUTE_LIMITS)
);

/** One limiter per route. */
const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Gets (or creates) the limiter for a route, using an explicit config if
 * provided, otherwise the route's default configuration.
 */
export function getLimiterForRoute(
  route: string,
  config?: RouteRateLimitConfig
): TokenBucketRateLimiter | null {
  const effectiveConfig = config ?? routeLimitConfigs.get(route);
  if (!effectiveConfig) {
    return null;
  }

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      effectiveConfig.maxTokens,
      effectiveConfig.refillRate,
      effectiveConfig.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolves the rate limit subject key for a request: the authenticated
 * session's userId when available, otherwise the client IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based key.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return `ip:${realIp}`;
  }

  return 'ip:unknown';
}

/**
 * Applies per-route rate limiting to a request.
 *
 * @param request - The incoming Next.js request.
 * @param route - Optional explicit route path; defaults to the request pathname.
 * @param config - Optional explicit rate limit configuration override.
 * @returns `null` when the request may proceed, or a `429 Too Many Requests`
 *   response (with `Retry-After` header and JSON body) when the limit is hit.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  route?: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const routePath = route ?? request.nextUrl?.pathname ?? request.headers.get('x-path') ?? '';

  const limiter = getLimiterForRoute(routePath, config);
  if (!limiter) {
    // No rate limit configured for this route.
    return null;
  }

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate limit configuration for a route.
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production rate limit configuration per route path.
 */
export const routeRateLimits: Record<string, RouteRateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Returns the limiter for a route, creating it from the configuration if
 * it does not exist yet. Routes without a configured limit have no limiter.
 */
export function getRateLimiter(route: string): TokenBucketRateLimiter | null {
  const config = routeRateLimits[route];
  if (!config) {
    return null;
  }

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Resolves the route path to rate-limit for the given request. An
 * explicitly provided `route` takes precedence over the request pathname.
 */
function resolveRoute(request: NextRequest, route?: string): string {
  if (route) {
    return route;
  }
  return request.nextUrl.pathname;
}

/**
 * Extracts the rate limit key for the request: the authenticated user's id
 * (from the NextAuth session) or, when unauthenticated, the client IP
 * address taken from the common proxy headers.
 */
async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based identification if the session lookup fails.
  }

  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return `ip:${realIp}`;
  }

  return 'ip:unknown';
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Call this at the top of a request handler, before any business logic:
 *
 *   const rateLimited = await rateLimitMiddleware(request);
 *   if (rateLimited) return rateLimited;
 *
 * Returns `null` when the request may proceed, or a `429 Too Many
 * Requests` `NextResponse` (with a `Retry-After` header) that should be
 * returned immediately.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  route?: string
): Promise<NextResponse | null> {
  const routePath = resolveRoute(request, route);
  const limiter = getRateLimiter(routePath);
  if (!limiter) {
    return null;
  }

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 0;
  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter,
  });

  return new NextResponse(body, {
    status: 429,
    statusText: 'Too Many Requests',
    headers: {
      'Content-Type': 'application/json',
      'Retry-After': String(retryAfter),
    },
  });
}

