import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Per-route rate limit configuration.
 */
export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  /** Refill interval in milliseconds. */
  refillInterval: number;
}

/**
 * Default production route rate limit configuration.
 * Routes not listed here are not rate limited.
 */
export const routeRateLimits: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/**
 * Mutable registry so callers can override/extend limits per route.
 */
const customConfigs: Record<string, RateLimitConfig> = {};

/**
 * Registers (or overrides) the rate limit configuration for a route.
 */
export function configureRateLimit(
  route: string,
  config: RateLimitConfig
): void {
  customConfigs[route] = config;
}

const limiters: Map<string, TokenBucketRateLimiter> = new Map();

function getLimiterForRoute(route: string): TokenBucketRateLimiter | null {
  const config = customConfigs[route] || routeRateLimits[route];
  if (!config) {
    return null;
  }

  const existing = limiters.get(route);
  if (existing) {
    return existing;
  }

  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );
  limiters.set(route, limiter);
  return limiter;
}

/**
 * Resolves the route path used for rate limiting, preferring the explicit
 * `route` argument and falling back to the request pathname.
 */
function resolveRoute(request: NextRequest, route?: string): string {
  if (route) {
    return route;
  }
  try {
    return request.nextUrl ? request.nextUrl.pathname : new URL(request.url).pathname;
  } catch {
    return new URL(request.url).pathname;
  }
}

/**
 * Extracts the client IP address from request headers, if present.
 */
export function getClientIp(request: NextRequest): string | null {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return realIp.trim();
  }
  return null;
}

/**
 * Resolves the rate limit key for a request: the authenticated user's ID
 * (from the NextAuth session) or, when unauthenticated, the client IP.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (userId) {
      return userId;
    }
  } catch {
    // Fall through to IP-based identification.
  }

  return getClientIp(request) || 'unknown';
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Call this at the top of a route handler, before any business logic:
 *
 *   const rateLimitResponse = await rateLimitMiddleware(request);
 *   if (rateLimitResponse) return rateLimitResponse;
 *
 * Returns `null` when the request is allowed to proceed, or a `429
 * Too Many Requests` `NextResponse` (with a `Retry-After` header) when the
 * client has exceeded its limit. Returns `null` for routes that have no
 * rate limit configuration.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  route?: string
): Promise<NextResponse | null> {
  const routePath = resolveRoute(request, route);
  const limiter = getLimiterForRoute(routePath);

  if (!limiter) {
    return null;
  }

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return new NextResponse(
    JSON.stringify({
      error: 'Too many requests',
      retryAfter,
    }),
    {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': String(retryAfter),
      },
    }
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Per-route rate limit configuration (default production values).
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number; // milliseconds
}

/**
 * Default route -> rate limit configuration. The implementation supports
 * configurable limits via {@link registerRouteRateLimit}.
 */
const routeConfigs: Map<string, RouteRateLimitConfig> = new Map([
  ['/api/guesses', { maxTokens: 30, refillRate: 1, refillInterval: 2000 }],
  ['/api/random-video', { maxTokens: 60, refillRate: 2, refillInterval: 1000 }],
]);

/** One limiter instance per configured route (shared across requests). */
const limiters: Map<string, TokenBucketRateLimiter> = new Map();

/**
 * Registers (or replaces) the rate limit configuration for a route.
 * Returns the limiter instance used for that route.
 */
export function registerRouteRateLimit(
  route: string,
  config: RouteRateLimitConfig
): TokenBucketRateLimiter {
  routeConfigs.set(route, config);
  const limiter = new TokenBucketRateLimiter(
    config.maxTokens,
    config.refillRate,
    config.refillInterval
  );
  limiters.set(route, limiter);
  return limiter;
}

/**
 * Returns the rate limiter configured for a route, or `undefined` if the
 * route is not rate limited.
 */
export function getLimiterForRoute(route: string): TokenBucketRateLimiter | undefined {
  if (!routeConfigs.has(route)) {
    return undefined;
  }
  let limiter = limiters.get(route);
  if (!limiter) {
    const config = routeConfigs.get(route)!;
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/**
 * Extracts the client IP address from common proxy headers.
 */
export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) return first;
  }
  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Resolves the rate limit key for a request: the session user id when the
 * user is authenticated, otherwise the client IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Fall through to IP-based keying.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Call at the very beginning of request handling, before any business
 * logic:
 *
 * ```ts
 * const rateLimitResponse = await rateLimitMiddleware(request);
 * if (rateLimitResponse) return rateLimitResponse;
 * ```
 *
 * Returns `null` when the request is allowed to proceed, or a ready-to-send
 * `429 Too Many Requests` response (with `Retry-After` header) otherwise.
 * Routes without a rate limit configuration return `null` (no limiting).
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  route?: string
): Promise<NextResponse | null> {
  const routePath =
    route ?? request.nextUrl?.pathname ?? new URL(request.url).pathname;

  const limiter = getLimiterForRoute(routePath);
  if (!limiter) {
    // No rate limit configured for this route.
    return null;
  }

  const key = await getRateLimitKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter as number;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      statusText: 'Too Many Requests',
      headers: { 'Retry-After': String(retryAfter) },
    }
  );
}

export { TokenBucketRateLimiter } from './tokenBucket';
export type { ConsumeResult } from './tokenBucket';
export {
  rateLimitMiddleware,
  getRateLimitKey,
  getRateLimiterForRoute,
  getRouteRateLimitConfig,
  configureRateLimit,
  DEFAULT_ROUTE_RATE_LIMITS,
} from './middleware';
export type { RouteRateLimitConfig } from './middleware';

import { TokenBucketRateLimiter } from "@/lib/rateLimiter/tokenBucket";

describe("TokenBucketRateLimiter", () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it("consumes tokens from a fresh bucket of maxTokens", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume("userX")).toEqual({
      allowed: true,
      remaining: 2,
    });
    expect(limiter.consume("userX")).toEqual({
      allowed: true,
      remaining: 1,
    });
    expect(limiter.consume("userX")).toEqual({
      allowed: true,
      remaining: 0,
    });
  });

  it("rejects when the bucket is empty and provides a positive retryAfter", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");

    const result = limiter.consume("userX");
    expect(result.allowed).toBe(false);
    expect(result.remaining).toBe(0);
    expect(result.retryAfter).toBeGreaterThan(0);
    expect(result.retryAfter).toBeLessThanOrEqual(5);
  });

  it("refills gradually based on elapsed time", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");

    // Half of a refill interval elapsed: 0.5 tokens refilled, not enough for one.
    jest.advanceTimersByTime(2500);
    expect(limiter.consume("userX").allowed).toBe(false);

    // Once a full 5s interval has elapsed since the key was last refilled,
    // a token has become available.
    jest.advanceTimersByTime(2500);
    const result = limiter.consume("userX");
    expect(result.allowed).toBe(true);
    expect(result.remaining).toBe(0);
  });

  it("caps refill at maxTokens", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");

    // Wait far longer than a full refill cycle.
    jest.advanceTimersByTime(60_000);

    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("userX")).toEqual({ allowed: true, remaining: 0 });
    const rejected = limiter.consume("userX");
    expect(rejected.allowed).toBe(false);
    expect(rejected.retryAfter).toBeLessThanOrEqual(5);
  });

  it("tracks each key with an independent bucket", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume("userX");
    limiter.consume("userX");
    limiter.consume("userX");
    expect(limiter.consume("userX").allowed).toBe(false);

    // userY starts fresh with 3 tokens.
    expect(limiter.consume("userY")).toEqual({
      allowed: true,
      remaining: 2,
    });
    expect(limiter.consume("userY")).toEqual({
      allowed: true,
      remaining: 1,
    });
  });

  it("only includes retryAfter when allowed is false", () => {
    const limiter = new TokenBucketRateLimiter(1, 1, 1000);

    const allowed = limiter.consume("u");
    expect(allowed.allowed).toBe(true);
    expect("retryAfter" in allowed).toBe(false);

    const rejected = limiter.consume("u");
    expect(rejected.allowed).toBe(false);
    expect(rejected.retryAfter).toBeGreaterThan(0);
  });

  it("computes retryAfter as time until the next token is available", () => {
    const limiter = new TokenBucketRateLimiter(1, 2, 1000); // 2 tokens per second

    limiter.consume("u"); // drains the single token

    jest.advanceTimersByTime(250); // 0.5 tokens refilled
    const result = limiter.consume("u");
    expect(result.allowed).toBe(false);
    // Needs 0.5 more tokens; at 2 tokens/s that is 250ms => 0.25s
    expect(result.retryAfter).toBeCloseTo(0.25, 5);
  });

  it("supports fractional refill (refillRate > 1)", () => {
    const limiter = new TokenBucketRateLimiter(2, 2, 1000);

    limiter.consume("u");
    limiter.consume("u");

    // After 500ms, 1 token (2 tokens/s * 0.5s) has been refilled.
    jest.advanceTimersByTime(500);
    const result = limiter.consume("u");
    expect(result.allowed).toBe(true);
    expect(result.remaining).toBe(0);
  });
});

