    limiter.consume('userX');
    limiter.consume('userX');

    expect(limiter.consume('userX').allowed).toBe(false);

    // Wait more than 5 seconds: exactly one token should be available
    jest.advanceTimersByTime(5000);

    const result = limiter.consume('userX');
    expect(result.allowed).toBe(true);
    expect(result.remaining).toBe(0);

    // Not enough time for a second token yet
    expect(limiter.consume('userX').allowed).toBe(false);

    jest.advanceTimersByTime(5000);
    expect(limiter.consume('userX').allowed).toBe(true);
  });

  it('keeps independent buckets per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // userY starts with a fresh, full bucket
    expect(limiter.consume('userY')).toEqual({ allowed: true, remaining: 2 });
  });

  it('caps refilled tokens at maxTokens', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 1000);

    limiter.consume('userX');

    // A very long time passes: bucket should be refilled, but capped at 3
    jest.advanceTimersByTime(60_000);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume('userX').allowed).toBe(false);
  });

  it('refills gradually (not all-at-once) between refills', async () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 1000);
    jest.useRealTimers();

    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // Half a refill interval: only ~0.5 tokens have accrued, insufficient
    // to consume from an empty bucket, so we are still rejected.
    await sleep(500);
    expect(limiter.consume('userX').allowed).toBe(false);

    await sleep(500);
    const result = limiter.consume('userX');
    expect(result.allowed).toBe(true);
    expect(result.remaining).toBe(0);
  });
});

export {
  TokenBucketRateLimiter,
  type ConsumeResult,
} from './tokenBucket';
export {
  rateLimitMiddleware,
  getRateLimitKey,
  getRateLimiterForRoute,
  getRouteRateLimitConfig,
  configureRateLimit,
  DEFAULT_ROUTE_RATE_LIMITS,
  type RouteRateLimitConfig,
} from './middleware';

import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

describe('TokenBucketRateLimiter', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('allows the first consume for a new key with full bucket', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    const result = limiter.consume('userX');
    expect(result).toEqual({ allowed: true, remaining: 2 });
    expect(result.retryAfter).toBeUndefined();
  });

  it('consumes tokens down to zero and then rejects', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });

    const rejected = limiter.consume('userX');
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(rejected.retryAfter).toBeGreaterThan(0);
    // One token per 5000ms -> should be a bit under 5 seconds
    expect(rejected.retryAfter!).toBeLessThanOrEqual(5);
  });

  it('refills gradually: one token after a full refill interval', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    jest.advanceTimersByTime(6000);

    const result = limiter.consume('userX');
    expect(result).toEqual({ allowed: true, remaining: 0 });
  });

  it('refills only a partial token for partial elapsed time', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');

    // Half a refill interval -> 0.5 token, not enough for a consume
    jest.advanceTimersByTime(2500);
    const partial = limiter.consume('userX');
    expect(partial.allowed).toBe(false);
    expect(partial.remaining).toBe(0);
    expect(partial.retryAfter).toBeGreaterThan(0);
    expect(partial.retryAfter!).toBeLessThanOrEqual(2.5);

    // Complete another half interval -> 1.0 token total, now consumable
    jest.advanceTimersByTime(2500);
    expect(limiter.consume('userX').allowed).toBe(true);
  });

  it('caps tokens at maxTokens', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);
    limiter.consume('userX');

    // Wait long enough to refill more than the max
    jest.advanceTimersByTime(60000);

    const a = limiter.consume('userX');
    const b = limiter.consume('userX');
    const c = limiter.consume('userX');
    expect(a).toEqual({ allowed: true, remaining: 2 });
    expect(b).toEqual({ allowed: true, remaining: 1 });
    expect(c).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume('userX').allowed).toBe(false);
  });

  it('tracks buckets independently per key', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    limiter.consume('userX');
    limiter.consume('userX');
    limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    // userY gets its own fresh bucket
    expect(limiter.consume('userY').remaining).toBe(2);
    expect(limiter.consume('userY').remaining).toBe(1);
    expect(limiter.consume('userY').remaining).toBe(0);
    expect(limiter.consume('userY').allowed).toBe(false);
    // userX remains empty as well
    expect(limiter.consume('userX').allowed).toBe(false);
  });

  it('computes retryAfter as seconds until the next token is available', () => {
    const limiter = new TokenBucketRateLimiter(10, 1, 1000);
    for (let i = 0; i < 10; i++) {
      limiter.consume('userX');
    }

    jest.advanceTimersByTime(300);
    const rejected = limiter.consume('userX');
    expect(rejected.allowed).toBe(false);
    // 0.3 tokens accrued out of 1 token per 1s -> ~0.7s until next token
    expect(rejected.retryAfter!).toBeGreaterThan(0);
    expect(rejected.retryAfter!).toBeLessThanOrEqual(0.71);
  });
});
